    private static void copy(InputStream input,File dest,long max)throws IOException{File parent=dest.getParentFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("无法创建资源目录");try(InputStream in=input;FileOutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException("文件不可读取");byte[] buf=new byte[32768];int n;long total=0;while((n=in.read(buf))!=-1){total+=n;if(total>max)throw new IOException("资源文件超过声明大小");out.write(buf,0,n);}out.getFD().sync();}}
