    private JSONObject installed()throws Exception{if(!index.exists()&&!new File(index.getPath()+".bak").exists())return new JSONObject().put("games",new JSONArray()).put("files",new JSONArray());return new JSONObject(text(new AtomicFile(index).openRead(),8*1024*1024));}
    synchronized JSONArray games()throws Exception{return installed().getJSONArray("games");}
    synchronized String verifyInstalled()throws Exception{JSONArray files=installed().getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);File path=resolve(f.getString("sha256"));if(path==null||!path.isFile()||path.length()!=f.getLong("bytes")||!digest(path).equals(f.getString("sha256")))return JSONObject.quote("资源缺失或损坏："+f.getString("path"));}return "null";}
    synchronized String version()throws Exception{return installed().optString("version","");}
    synchronized String state()throws Exception{JSONObject o=installed();return new JSONObject().put("version",o.optString("version","")).put("addedHashes",o.optJSONArray("addedHashes")).toString();}
    synchronized String presence(String json)throws Exception{JSONArray list=new JSONArray(json);JSONObject result=new JSONObject();for(int i=0;i<list.length();i++){JSONObject g=list.getJSONObject(i);String hash=g.getString("hash"),path=g.getString("path");boolean exists=false;File f=resolve(hash);if(f!=null)exists=f.isFile()&&f.length()==g.getLong("bytes");else if(context!=null&&!path.contains("..")&&!path.startsWith("/")){if(g.optString("system","nes").equals("nes"))try(InputStream in=context.getAssets().open(path)){exists=true;}catch(IOException ignored){}else{f=new File(context.getFilesDir(),path);exists=f.isFile()&&f.length()==g.getLong("bytes");}}result.put(hash,exists);}return result.toString();}
    synchronized File resolve(String hash)throws Exception{if(!hash.matches("[a-f0-9]{64}"))throw new IOException("游戏身份无效");JSONArray files=installed().getJSONArray("files");for(int i=files.length()-1;i>=0;i--){JSONObject f=files.getJSONObject(i);if(hash.equals(f.getString("sha256"))){File path=new File(root,f.getString("stored"));if(!path.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("资源索引路径无效");return path;}}return null;}
    HallResources(File dir,JSONArray catalog){context=null;root=new File(dir,"resource-generations");root.mkdirs();index=new File(dir,"resource-index.json");catalogOverride=catalog;recover();}
    synchronized String status(){return status;}
    private void phase(String p,String error){try{JSONObject v=new JSONObject();v.put("phase",p);if(error!=null)v.put("error",error);status=v.toString();}catch(Exception ignored){}}
    synchronized void downloading(long bytes,long total){try{status=new JSONObject().put("phase","downloading").put("label","正在下载资源包："+(total>0?bytes*100/total:0)+"%（"+bytes/1048576+" MB）").toString();}catch(Exception ignored){}}
    synchronized void fail(String message){phase("failed",message);}
    synchronized void waiting(){cancel();phase("choosing",null);}
    synchronized void cancel(){generation++;if(prepared!=null)remove(prepared);prepared=null;manifest=null;phase("cancelled",null);}
    void prepare(final Uri uri){final int ticket;synchronized(this){ticket=++generation;phase("checking",null);}new Thread(new Runnable(){public void run(){try{inspect(uri,ticket);}catch(Exception e){synchronized(HallResources.this){if(generation==ticket)fail(e.getMessage());}}}},"pack-inspect").start();}
    String prepareFileForCheck(File file){cancel();int ticket=++generation;phase("checking",null);try{inspectFile(file,ticket);return status;}catch(Exception e){fail(e.getMessage());return status;}}
    private void inspect(Uri uri,int ticket)throws Exception{
        if("file".equals(uri.getScheme())){File owned=new File(uri.getPath());if(owned.getCanonicalPath().startsWith(context.getCacheDir().getCanonicalPath()+File.separator)){try{inspectFile(owned,ticket);}finally{owned.delete();}return;}}
        File zip=File.createTempFile("resource-",".zip",context.getCacheDir());
        try{copy(context.getContentResolver().openInputStream(uri),zip,2147483647L);inspectFile(zip,ticket);}finally{zip.delete();}
    }
